# Define the Euclidean algorithm function that supports memoization
@lru_cache(maxsize=None)
def gcd(x, y):
    return x if y == 0 else gcd(y, x % y)

# Define the function memoized_powers that calculates the specified powers
@lru_cache(maxsize=None)
def memoized_powers(x, r, n, mod):
    if r == -1:
        return n % mod
    num, den = n // (2 ** r), n // (2 ** r)
    return ((num + n // 2) * memoized_powers(x, r - 1, int(den * x // num), mod)) % mod

