def top_sort(tree: List[List[int]]) -> List[int]:
    order = []
    done = set()
    for i in range(1, n):
        visited = [False] * n
        stack = [(i, -i)]
        visited[i] = True
        while stack:
            i, w = stack.pop()
            if i not in done:
