from bisect import bisect_left

def max_monsters(n: int, m: int, monster_cells: List[int], special_cells: List[int]) -> int:
    monster_cells.sort()
    special_cells.sort()

    monster_blocks = []
    for i in range(1, n + 1):
        block_index = bisect_left(monster_cells, i)
        if block_index < len(monster_cells):
            block_id = monster_cells[block_index] - i
        else:
            block_id = None
        if block_id:
            block_index -= 1
        monster_blocks.append((block_index, i, block_id))

    for i in range(m):
        block = (special_cells[i] - 1, -1)
        if '*' in block:
            block = block
        else:
            if max(0, i - 15) >= 0 and (monster_cells[i - 15] - special_cells[i - 15] > i) and i > 15:
                special_cells[i] = special_cells[i - 15]
            if (i == len(special_cells) - 1) and i < len(monster_blocks) - 1:
                block = monster_blocks[i + 1]
        else:
            block = monster_blocks[i]
        special_cells[block[0]] = i + 1

    return max(special_cells)

