def matrix_transform(matrix, operations):
    # Sort operations by left bound (di - ai) to process overlapping operations first
    operations.sort(key=lambda x: x[2] - x[0])

    # Mapping from the result of a left operation to the right operation
    transform_cache = defaultdict(lambda: [-1])

