                transform_id = transform_cache[(start_row, start_col)]
                if transform_id != -1:
                    result[start_index][start_col_index] = apply_transform(result[start_index][start_col_index], transform_cache[(start_row, start_col)], transform_id)
                else:
                    result[start_index][start_col_index] = apply_transform(result[start_index][start_col_index], transform_cache[(start_row, start_col)], 0)
        transform_cache[(start_row, start_col)] = transform_id

    return result

def apply_transform(cell, transform_cache, cache_id):
    if cache_id == -1:
        cache_id = transform_cache[transform_cache[(transform_cache[(transform_cache.keys())[0][0], transform_cache.keys()[0][1]]), (transform_cache.keys()[0][0], transform_cache.keys()[0][1])]]
