def matrix_transform(rows: int, columns: int, operations: List[Tuple[List[int], List[int], List[int], List[int], int, int]]) -> List[List[int]]:
    m = [[(row, col, (0, 0)), (row, col, (1, 1))] for row in range(rows) for col in range(columns)]
