def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

def factorize(n):
    factors = []
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            factors.append(i)
            if i != n // i:
                factors.append(n // i)
    return factors

def fr(n, r):
    if r == 0:
        return 1
    factors = factorize(n)
    count = 1
    for i in factors:
        if gcd(i, n // i) == 1:
            count += 2 * fr(n // i, r - 1) if r > 0 else fr(n // i, r - 1)
            count %= 10**9 + 7
    return count

