from collections import deque

def solve(n, m, monster_cells, special_cells):
    monster_cells.sort()
    special_cells.sort()

    dq = deque()
    for monster in monster_cells:
        seen = set()
        q_dq = deque([monster])
        dq.append((monster, set([monster])))

        while q_dq:
            val, seens = q_dq.popleft()

            for neigh in [(val+1)%n, (val-1+n)%n]:
                if neigh in seens or neigh < 0 or neigh >= n:
                    continue
                seen = seens | {neigh}
                if neigh in special_cells:
                    seen_size = len(seen)
                    dq.append((neigh, seen))
                    if seen_size == m:
                        return len(special_cells)

                if neigh in dq:
                    dq.remove((neigh, seen))

    return len(special_cells)

