from math import inf

def find_longest_common_prefix(symbols: List[str]) -> int:
    if len(symbols) == 0:
        return 0
    else:
        m = len(symbols)
        for i in range(m - 1):
            if symbols[i][-1] != symbols[i + 1][0]:
                return i
        return m

def find_min_edges(dag: List[List[int]]) -> int:
    result = 0
    for x, y in dag:
        result += x - 1
    return result

def k_similar_members(arr: List[int], interval: List[int]) -> List[int]:
    intervals_per_member_dict = {}
    for a in arr:
        if a in intervals_per_member_dict:
            intervals_per_member_dict[a].add((interval[0], interval[1]))
        else:
            intervals_per_member_dict[a] = {(interval[0], interval[1])}

    all_similar_member_intervals = set([])
    for value, intervals in intervals_per_member_dict.items():
        if len(intervals) == 1:
            all_similar_member_intervals |= intervals

    if len(all_similar_member_intervals) == 0:
        return [0]

    global_prefix = find_longest_common_prefix(
        [interval[0] for interval in all_similar_member_intervals]
    )
    components = [[]]
    last = intervals_per_member_dict
    while True:
        for a in sorted(last):
            if global_prefix < find_longest_common_prefix([interval[1] for interval in last[a]]):
                global_prefix = find_longest_common_prefix([interval[1] for interval in last[a]])
                components = [last[a]]
                break
            components.append(last[a])
        last = sorted(last[a] for a in last if not last[a])
        if not last:
            break

    sorted_interval = [interval[0] for interval in all_similar_member_intervals]
    min_edges = find_min_edges(all_similar_member_intervals)
    if min_edges == 0:
        return [0]

    for i in range(len(components) - 1, 0, -1):
        edges_count_per_vertex = {}
        for j, interval in enumerate(components[i-1]):
