def count_subsquares(n, q, colors):
    """
    Counts the number of k x k subarrays with at most q distinct colors.
    """
    count = 0
    for k in range(1, n + 1):
        for i in range(n - k + 1):
            for j in range(n - k + 1):
                current_colors = set()
                for r in range(i, i + k):
                    for c in range(j, j + k):
                        current_colors.add(colors[r][c])
                if len(current_colors) <= q:
                    count += 1
    return count

