from math import gcd
from fractions import Fraction

MOD = 10**9 + 7

# Computes C(n, k) mod MOD using Lucas' Theorem
def nck_mod_fact(n, k):
    C = 1
    while k:
        if k & 1:
            C = C * n / (float(k) + 1) % MOD
        n, k = n // (k + 1), (k + 1) // 2
    return C

# Computes pmod(n, mod) without overflow
def po_mod_base_mod(to, base, mod):
    p = base
    for i in range(1, to + 1):
        p = p * base % mod
    return p

# Computes C(n, k) mod MOD * r^(n-k) using factorials
def factorials_mod(n, mod):
    res = 1
    for i in range(1, n + 1):
        res = res * Fraction(int(i * po_mod_base_mod(n - i, i, MOD) % MOD))
    return int(res)

def bk(m, d):
    return factorials_mod(m, d + MOD - 1) * po_mod_base_mod(d, MOD - 2, MOD) % MOD

# Computes fr(n, r) using lookup table if r is fixed
def lookup_table_if_r_fixed(n, r_min, r_max, r_list):
    r_max %= MOD
    n = n % MOD
    lookup = [0] * (r_max + 1)
    for r in r_list:
        lookup[r] = bk(n, r)
    return lookup[n]


# Computes fr(n, r) recursively
def fr(n, r, memo={}):
    r %= MOD
    r_max = min(10**6, r + 1)
    r_min = 0 if r == 0 else 1
    r_bound = lookup_table_if_r_fixed(n, r_min, r_max, r_list)
    for r_prime in range(r_bound, r_min, -1):
        r_del = r - r_prime
        if r_del < r_min:
            continue
        r_del_bound = lookup_table_if_r_fixed(n, r_del, r_max, r_list)
        x = lookup_table_if_r_fixed(n, n - r_prime, r_max, r_list)
        memo[r] = int(x - (pow(2, n - r_prime - 1, MOD) - 1) * \
                    (lookup_table_if_r_fixed(n, n - r_prime - r, r_max, r_list)) % MOD) % MOD
    return memo[r]

# Compute fr(n, r)
def compute_fr(n, r, mod=MOD, memo=None):
    if memo is None:
        memo = {}
    r %= MOD
    for i in range(r_max := min(10**6, r + 1)):
        memo[i] = fr(n, r, r == 0, memo)
    return memo[r % MOD]

# Compute fr(n)
def compute_fr_(n, mod=MOD, memo=None):
    if memo is None:
        memo = {}
    for i in range(r_max := min(10**6, n + 1)):
        memo[i] = fr(n, i, r_max == 0, memo)
    return memo[n % MOD]
