import collections

class TripletTracker:
    def __init__(self):
        self.triplets = set()
        self.edges = collections.defaultdict(set)

    def remove_edge(self, u, v):
        self.edges[u].remove(v)
        self.edges[v].remove(u)
        self.triplets -= {(u, v, x) for x in self.residual_path(u, v) if (u, v, x) not in self.triplets}

    def add_edge(self, u, v):
        self.edges[u].add(v)
        self.edges[v].add(u)
        self.triplets |= {(u, v, x) for x in self.residual_path(u, v) if (u, v, x) not in self.triplets}

    def residual_path(self, u, v):
        stack = [(u, 0)]
        visited = set()
        path = []
        while stack:
            parent, flow = stack.pop()
            if parent == v or not visited:
                visited.add(parent)
                path.append(parent)
                if parent == v:
                    break
                for neighbor in self.edges[parent]:
                    if neighbor not in visited and (flow, neighbor) not in self.edges[parent]:
                        stack.append((neighbor, max(0, flow)))
        return path

    def query(self, u, v, w):
        return len(self.triplets)

# Example usage
n = int(input())
edges = [tuple(map(int, input().split())) for _ in range(n - 1)]
disconnected_pairs = {tuple(map(int, input().split())) for _ in range(int(input()))}
tracker = TripletTracker()
for u, v in edges:
    tracker.add_edge(u, v)
for a, b in disconnected_pairs:
    if (a, b) not in tracker.edges[a] and (a, b) not in tracker.edges[b]:
        tracker.add_edge(a, b)
print(tracker.query(*tuple(int(x) for x in input().split())))
