def count_subquads(n, q, c):
    dp = [0] * (n + 1)
    dp[0] = 1
    result = 0

    for subquadrant in c:
        for i in range(1, n + 1):
            for j in range(0, n + 1):
                if dp[j] <= q:
                    dp[j] += dp[j - i] + dp[i + j - 1]
                    dp[j] %= q
                else:
                    break

        result += len(subquadrant)
        result %= q

    return result

n, q = map(int, input().strip().split())
