def mod_exponentiation(base, exponent, mod):
    result = 1
    base = base % mod

    while exponent > 0:
        if (exponent % 2) == 1:
            result = (result * base) % mod

        exponent = exponent >> 1
        base = (base * base) % mod

    return result

def factorial_modulo(n, mod):
    fact = 1
    for i in range(1, n + 1):
        fact = (fact * i) % mod

    return fact

def f0(n, mod):
    if n == 1:
        return 1
    return 2 * (n - 1) // 2 - (factorial_modulo(n - 1, mod) // factorial_modulo(2, mod) * 2) % mod

def fr(n, r, mod):
    if r == 0 and n == 1:
        return 1
    if r == 0 or n == 1:
        return 0

    u = n
    v = n

    for i in range(r + 1):
        if i % 2 == 0:
            u = u * (n - (i // 2)) % mod
        else:
            v = v * (n - (i // 2)) % mod
        u, v = u % mod, v % mod

    return (mod_exponentiation(u, mod - 2, mod) * v) % mod

q = int(input())
for _ in range(q):
    r, n = map(int, input().split())
    print(fr(n, r, 1000000007))
